"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[98800],{52520:i=>{i.exports=JSON.parse('{"tag":{"label":"chinchillas","permalink":"/docs/tags/chinchillas","allTagsPath":"/docs/tags","count":23,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Chinchillas/getting-started/nutrition","title":"Chinchilla Nutrition and Diet","description":"A chinchilla\'s digestive system is incredibly sensitive and has evolved to process a diet of sparse, high-fiber vegetation. Providing a species-appropriate diet is the single most important thing you can do to ensure your chinchilla lives a long, healthy life. This guide covers the essential components of a healthy chinchilla diet.","permalink":"/docs/Chinchillas/getting-started/nutrition"},{"id":"Chinchillas/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Chinchillas","description":"An overview of the most common health issues affecting pet chinchillas, including dental disease, bloat, ringworm, and heat stroke, with a focus on prevention and recognizing early warning signs.","permalink":"/docs/Chinchillas/illnesses-and-conditions/common-health-issues"},{"id":"Chinchillas/illnesses-and-conditions/dental-disease-in-chinchillas","title":"Dental Disease in Chinchillas","description":"Learn about the causes, symptoms, and treatment of dental disease and malocclusion in chinchillas, including how diet and genetics play a role.","permalink":"/docs/Chinchillas/illnesses-and-conditions/dental-disease-in-chinchillas"},{"id":"Chinchillas/health-and-wellness/dental-health","title":"Dental Health in Chinchillas","description":"A detailed guide to dental disease in chinchillas, covering the causes of malocclusion, recognizing the signs of dental problems, and the critical role of a high-hay diet in prevention.","permalink":"/docs/Chinchillas/health-and-wellness/dental-health"},{"id":"Chinchillas/illnesses-and-conditions/diabetes-in-chinchillas","title":"Diabetes in Chinchillas","description":"Learn about the causes, symptoms, diagnosis, and management of diabetes mellitus in chinchillas, including diet and lifestyle changes.","permalink":"/docs/Chinchillas/illnesses-and-conditions/diabetes-in-chinchillas"},{"id":"Chinchillas/getting-started/essential-supplies","title":"Essential Supplies for Pet Chinchillas","description":"A complete checklist of the essential supplies required to create a safe, healthy, and enriching environment for pet chinchillas.","permalink":"/docs/Chinchillas/getting-started/essential-supplies"},{"id":"Chinchillas/health-and-wellness/eye-and-vision-issues","title":"Eye & Vision Issues in Chinchillas","description":"A guide to common eye and vision issues in chinchillas, including watery eyes (epiphora) as a sign of dental disease, conjunctivitis, and corneal ulcers.","permalink":"/docs/Chinchillas/health-and-wellness/eye-and-vision-issues"},{"id":"Chinchillas/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Chinchillas","description":"An essential guide to gastrointestinal (GI) health in chinchillas, covering their sensitive digestive system, the causes and signs of life-threatening bloat and GI stasis, and the importance of a high-hay diet.","permalink":"/docs/Chinchillas/health-and-wellness/gi-health"},{"id":"Chinchillas/getting-started/grooming-your-chinchilla","title":"Grooming Your Pet Chinchilla","description":"A guide to the unique grooming needs of chinchillas, focusing on the importance of dust baths and how to provide them safely.","permalink":"/docs/Chinchillas/getting-started/grooming-your-chinchilla"},{"id":"Chinchillas/illnesses-and-conditions/heartdisease","title":"Heart Disease and Heart Failure in Chinchillas","description":"Heart disease and heart failure are relatively uncommon in chinchillas but can still occur, especially as they age or due to certain genetic predispositions. These conditions can be challenging to detect early on, as chinchillas tend to hide their symptoms until the disease has progressed. Understanding the causes, signs, and treatments of heart disease in chinchillas is key to ensuring your pet remains healthy and receives proper care.","permalink":"/docs/Chinchillas/illnesses-and-conditions/heartdisease"},{"id":"Chinchillas/illnesses-and-conditions/heat-stroke-in-chinchillas","title":"Heat Stroke in Chinchillas","description":"Learn how to recognize, prevent, and respond to heat stroke in chinchillas, including emergency first aid and safe temperature ranges.","permalink":"/docs/Chinchillas/illnesses-and-conditions/heat-stroke-in-chinchillas"},{"id":"Chinchillas/health-and-wellness/home-health-care","title":"Home Health Care for Your Chinchilla","description":"Chinchillas are masters at hiding illness, a survival instinct inherited from their wild ancestors. This means that by the time a chinchilla shows obvious signs of being sick, they may have been unwell for some time. Performing regular health checks at home is one of the most effective ways to catch potential problems early. This guide will walk you through how to conduct a gentle, thorough health check for your chinchilla.","permalink":"/docs/Chinchillas/health-and-wellness/home-health-care"},{"id":"Chinchillas/getting-started/is-a-chinchilla-right-for-me","title":"Is a Chinchilla Right for Me and My Family?","description":"Chinchillas are extraordinary animals \u2014 soft as velvet, agile as acrobats, and capable of living 20 years or more with excellent care. That extraordinary lifespan is also the most important thing to...","permalink":"/docs/Chinchillas/getting-started/is-a-chinchilla-right-for-me"},{"id":"Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds","title":"Know Your Chinchilla Breeds","description":"An overview of chinchilla species and the wide variety of color mutations found in pet chinchillas.","permalink":"/docs/Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds"},{"id":"Chinchillas/health-and-wellness/parasites","title":"Parasites in Chinchillas","description":"A guide to parasites in chinchillas, covering common internal parasites like Giardia and external parasites like fleas and mites, as well as the fungal infection ringworm.","permalink":"/docs/Chinchillas/health-and-wellness/parasites"},{"id":"Chinchillas/illnesses-and-conditions/parasites-in-chinchillas","title":"Parasites in Chinchillas","description":"Learn about external and internal parasites that can affect chinchillas, including mites, fleas, giardia, and how to prevent and treat infestations.","permalink":"/docs/Chinchillas/illnesses-and-conditions/parasites-in-chinchillas"},{"id":"Chinchillas/getting-started/proper-handling","title":"Proper Handling of Pet Chinchillas","description":"A guide to safely and confidently handling pet chinchillas, with techniques for building trust and correctly picking them up.","permalink":"/docs/Chinchillas/getting-started/proper-handling"},{"id":"Chinchillas/illnesses-and-conditions/respiratory-infections-in-chinchillas","title":"Respiratory Infections in Chinchillas","description":"Learn about the causes, symptoms, treatment, and prevention of respiratory infections in chinchillas, including bacterial pneumonia and environmental risk factors.","permalink":"/docs/Chinchillas/illnesses-and-conditions/respiratory-infections-in-chinchillas"},{"id":"Chinchillas/health-and-wellness/respiratory-issues","title":"Respiratory Issues in Chinchillas","description":"A guide to respiratory infections in chinchillas, covering the causes, signs of illness, and the importance of a clean, well-ventilated environment for prevention.","permalink":"/docs/Chinchillas/health-and-wellness/respiratory-issues"},{"id":"Chinchillas/breeds-and-genetics/sexing-your-chinchilla","title":"Sexing Your Pet Chinchilla","description":"A clear and simple guide to determining the sex of a pet chinchilla by examining the anogenital distance and key anatomical features.","permalink":"/docs/Chinchillas/breeds-and-genetics/sexing-your-chinchilla"},{"id":"Chinchillas/getting-started/chinchilla-habitat","title":"The Ideal Chinchilla Habitat","description":"Creating a safe, stimulating, and comfortable habitat is essential for your chinchilla\'s physical and mental well-being. Chinchillas are active, curious, and fragile animals, and their environment must be tailored to their unique needs. This guide details the critical components of an ideal chinchilla habitat.","permalink":"/docs/Chinchillas/getting-started/chinchilla-habitat"},{"id":"Chinchillas/health-and-wellness/understanding-chinchilla-behavior","title":"Understanding Chinchilla Behavior: A Guide for Owners","description":"Chinchillas are active, curious animals with a surprisingly rich behavioral repertoire. They are crepuscular \u2014 most active at dawn and dusk \u2014 and can live for 15 years or more.","permalink":"/docs/Chinchillas/health-and-wellness/understanding-chinchilla-behavior"}],"unlisted":false}}')}}]);